  builder_.add_SELECTED_COUNT(SELECTED_COUNT);
  builder_.add_MNV_RECORDS(MNV_RECORDS);
  builder_.add_OCM_RECORDS(OCM_RECORDS);
  builder_.add_OMM_RECORDS(OMM_RECORDS);
