  builder_.add_POSITION_TOLERANCE_KM(POSITION_TOLERANCE_KM);
  builder_.add_FRAME_TRANSFORMATION_REF(FRAME_TRANSFORMATION_REF);
  builder_.add_FORCE_MODEL_LIMITATION(FORCE_MODEL_LIMITATION);
